import {studioRoute,unitRoute,sharedCollection,STUDIO_KEY,validateStudioNotes,decodeStudioBackup} from './studio-core.js?v=2.1.0';
import {namedGrammar} from './library.js?v=1.5.2';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let notes={},pending=null,currentUnit=null,filter='',collection=[],lastRoute='',lastWriter='clara',requestedScroll=null,loadingFrame=false;
try{const old=JSON.parse(localStorage.getItem(STUDIO_KEY)||'{}');if(validateStudioNotes(old))notes=old;}catch{}
function toast(text){$('#studio-status').textContent=text;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#studio-status').textContent='',5000);}
function save(){try{localStorage.setItem(STUDIO_KEY,JSON.stringify(notes));}catch{toast('Dein Browser konnte die Notiz nicht speichern. Sichere dein Journal als Datei.');}}
function field(key,label,placeholder=''){return `<label class="field" for="studio-${key}">${esc(label)}</label><textarea id="studio-${key}" data-studio-note="${key}" maxlength="30000" placeholder="${esc(placeholder)}">${esc(notes[key]||'')}</textarea>`;}
function modal(html){$('#studio-dialog-content').innerHTML=html;$('#studio-dialog').showModal();}
$('.dialog-close').onclick=()=>$('#studio-dialog').close();
function home(){return `<section class="studio-hero"><div><p class="eyebrow">Eine Werkstatt · Clara Lösel & Bodo Wartke</p><h1>Was können<br><em>deine Worte?</em></h1><p class="intro">Fang mit einem Satz an. Hör den beiden zu. Schreib etwas, das du auf deine eigene Weise formulierst.</p><div class="actions"><a class="button primary" href="#schreiben/clara">Selbst etwas schreiben</a><a class="button" href="#vergleich">Beide verbinden</a></div><p class="small">Du darfst erfinden. Persönliche Erfahrungen sind keine Voraussetzung.</p></div><section class="line-lab" aria-label="Mit einer Zeile experimentieren"><p class="line-original">Der Ausgangssatz: «Ich habe viel im Kopf.»</p><div id="live-line" class="live-line" aria-live="polite"></div><div class="line-tools" role="group" aria-label="Sprachliche Wirkung ausprobieren"><button data-line="bild" aria-pressed="true">Ein Bild finden</button><button data-line="wiederholung" aria-pressed="false">Wiederholen</button><button data-line="wendung" aria-pressed="false">Anders enden</button></div><p id="line-feedback" class="line-feedback"></p><button class="primary" id="write-live-line">Mit dieser Zeile weiterschreiben</button><p class="small" style="margin-top:16px">Eigens geschriebene Übungszeilen, keine Originaltexte.</p></section></section><section class="artist-grid" aria-label="Zwei Zugänge zum eigenen Schreiben"><article class="artist-card clara"><p class="eyebrow">Clara Lösel · Gedichte, Stimme, Gegenwart</p><h2>Was dich beschäftigt,<br>bekommt Worte.</h2><p class="artist-subtitle">Nähe. Widerspruch. Eine überraschende Wendung.</p><a class="artist-photo" href="#clara/inspiration"><img src="assets/clara-loesel-offiziell.jpg" alt="Clara Lösel" loading="lazy"><span>Clara Lösel · Gedichte und Original-Reels ↗</span></a><p>Höre Original-Reels, entdecke Alltagsbilder und erprobe, wie eine Zeile ihre Richtung ändert.</p><div class="actions"><a class="button primary" href="#clara/inspiration">Originale entdecken</a><a class="button" href="#schreiben/clara">Eigene Gedichte schreiben</a></div></article><article class="artist-card wartke"><p class="eyebrow">Bodo Wartke · Sprache, Klang, Wissen</p><h2>Ein sperriges Wort<br>gerät in Bewegung.</h2><p class="artist-subtitle">Anlaute. Takt. Ein Reim, der etwas trägt.</p><a class="artist-photo" href="#wartke/start"><img src="https://i.ytimg.com/vi/hT42JFmxHII/hqdefault.jpg" alt="Bodo Wartke und Marti Fischer im Originalvideo Barbaras Rhabarberbar" loading="lazy" referrerpolicy="no-referrer"><span>▶ Bodo Wartke · Auftritt ansehen</span></a><p>Höre, wie Fachbegriffe und Zungenbrecher klingen. Mach daraus eigene Verse, deren Inhalt du erklären kannst.</p><div class="actions"><a class="button primary" href="#wartke/start">Originale entdecken</a><a class="button" href="#schreiben/wartke">Eigene Lernverse schreiben</a></div></article></section><section><p class="eyebrow">Du entscheidest, wo es beginnt</p><h2>Hören. Verändern. Selber sagen.</h2><div class="studio-grid"><article class="panel"><h3>Eine Stelle finden</h3><p>Was fällt dir am Vortrag auf? Halte einen Klang, ein Bild oder eine Zeitstelle fest.</p><a href="#clara/inspiration">Mit Lösel anfangen</a></article><article class="panel lilac"><h3>Mit der Form spielen</h3><p>Verschiebe Zeilen, ändere einen Auftakt oder lass einen Begriff in anderem Tempo sprechen.</p><a href="#wartke/form">Formen ausprobieren</a></article><article class="panel gold"><h3>Etwas Eigenes behalten</h3><p>Deine Entwürfe und Grammatiken findest du gemeinsam wieder. Du kannst in beiden Schreibweisen weiterarbeiten.</p><a href="#sammlung">Meine Sammlung öffnen</a></article></div></section><section class="panel section-gap"><h2>Welches Wort lässt dich gerade nicht los?</h2>${field('start','Dein Wort oder Gedanke','Ein Gegenstand, ein Fachwort, eine Beobachtung …')}<div class="actions"><button id="start-clara">Als Gedicht weiterdenken</button><button id="start-wartke">Als Lernvers weiterdenken</button></div></section>`;}
const lines={bild:{text:'In meinem Kopf fährt jeder Zug zugleich.',hint:'Ein innerer Zustand wird als konkretes Bild vorstellbar. Welcher Gegenstand würde zu deinem Gedanken passen?'},wiederholung:{text:'Ich denke an morgen.\nIch denke an gestern.\nIch denke: Wann bin ich hier?',hint:'Der gleiche Auftakt hält die Zeilen zusammen. Die letzte Zeile verschiebt die Frage.'},wendung:{text:'Ich wollte meinen Kopf leeren.\nDann fand ich eine Zeile, die bleiben durfte.',hint:'Der Schluss verändert die Absicht vom Anfang. Schreibe eine andere letzte Zeile und vergleiche die Wirkung.'}};
function startWriting(unit,text){if(!text.trim())return toast('Schreibe zuerst ein Wort oder wähle eine Zeile.');pending={type:'lyrik:prompt',text};location.hash='#schreiben/'+unit;}
function bindHome(){let chosen='bild';const draw=()=>{$('#live-line').innerHTML=lines[chosen].text.split('\n').map(line=>line.split(' ').map((word,i)=>`<span style="animation-delay:${i*.025}s">${esc(word)}</span>`).join(' ')).join('<br>');$('#line-feedback').textContent=lines[chosen].hint;document.querySelectorAll('[data-line]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.line===chosen)));};document.querySelectorAll('[data-line]').forEach(b=>b.onclick=()=>{chosen=b.dataset.line;draw();});$('#write-live-line').onclick=()=>startWriting('clara',lines[chosen].text);$('#start-clara').onclick=()=>startWriting('clara',$('#studio-start').value);$('#start-wartke').onclick=()=>startWriting('wartke',$('#studio-start').value);draw();}
function comparison(){return `<p class="eyebrow">Zwei Zugänge, ein eigener Versuch</p><h1>Was trägt eine Zeile:<br><em>Bild, Klang oder Wissen?</em></h1><p class="intro">Wähle eine Stelle von Lösel und eine von Wartke. Sammle Beobachtungen und verwandle danach dasselbe eigene Thema auf zwei verschiedene Arten.</p><div class="studio-grid"><section class="panel"><h2>Bei Lösel hinhören</h2><p>Wo wird etwas Abstraktes zu einem Alltagsbild? Wo kippt eine Erwartung? Nenne eine Stelle und ihre Wirkung.</p><a href="#clara/inspiration">Gedichte und Reels auswählen</a>${field('vergleich-clara','Deine Beobachtung zu Lösel','Titel · Zeitstelle oder Seite · sprachliche Beobachtung · Wirkung')}</section><section class="panel lilac"><h2>Bei Wartke hinhören</h2><p>Welche Lautfolge, Wiederholung oder Gliederung fällt auf? Trenne das Erinnern des Klangs vom Erklären des Inhalts.</p><a href="#wartke/hoeren">Hörbeispiel auswählen</a>${field('vergleich-wartke','Deine Beobachtung zu Wartke','Titel · Zeitstelle · sprachliche Beobachtung · fachlicher Kern')}</section><section class="panel gold"><h2>Dein Thema verändern</h2><p>Schreibe vier Zeilen mit einem Bild oder einer Wendung. Schreibe dann vier Zeilen, die einen überprüften Zusammenhang merkbar machen. Was muss jeweils erhalten bleiben?</p>${field('vergleich-eigen','Dein Thema und deine Versuche','Du kannst über denselben Gegenstand ganz verschieden schreiben.')}<div class="actions"><button id="compare-write-clara">Mit Bildern weiterschreiben</button><button id="compare-write-wartke">Mit Wissen weiterschreiben</button></div></section></div><section class="panel"><h2>Prüfe, was dein Text leistet.</h2>${field('vergleich-rueckblick','Eine Entscheidung, die du begründen kannst','Welche Form hat dir geholfen? Was ging beim Umformulieren verloren? Was prüfst du an einer Fachquelle oder am Originaltext?')}</section>`;}
function collectionPage(){return `<p class="eyebrow">Deine Entwürfe an einem Ort</p><h1>Meine <em>Sammlung.</em></h1><p class="intro">Hier stehen eigene Editorentwürfe und gespeicherte Grammatiken aus beiden Zugängen zusammen. Wähle einen Text und entscheide, in welcher Schreibweise du daran weiterarbeiten möchtest.</p><div class="collection-controls"><div><label class="field" for="collection-search">Name, Wort oder Wendung suchen</label><input type="text" id="collection-search" value="${esc(filter)}"></div><div><label class="field" for="collection-target">Damit weiterarbeiten bei</label><select id="collection-target"><option value="clara">Lösel · Bilder und Stimme</option><option value="wartke">Wartke · Form und Lernverse</option></select></div></div><button id="collection-refresh">Sammlung neu einlesen</button><p id="collection-status" class="connection" style="margin-top:18px" role="status"></p><div id="collection-list" class="collection-grid"></div>`;}
function readCollection(){try{const result=sharedCollection(localStorage.getItem('zwischen-zeilen-v1'),localStorage.getItem('wartke-form-gedaechtnis-v1'));collection=result.entries;$('#collection-status').textContent=result.errors.join(' ');drawCollection();}catch(error){$('#collection-status').textContent=error.message;}}
function drawCollection(){const query=filter.toLocaleLowerCase('de'),found=collection.map((e,i)=>({...e,index:i})).filter(e=>(e.grammar.name+' '+e.grammar.rules+' '+e.grammar.words).toLocaleLowerCase('de').includes(query));$('#collection-list').innerHTML=found.length?found.map(e=>`<article class="panel collection-card"><p class="eyebrow">${e.unit==='clara'?'Lösel · Bilder und Stimme':'Wartke · Form und Wissen'}</p><h2>${esc(e.grammar.name)}</h2><p class="small">${esc(e.origins.join(' · '))}</p><details><summary>Regeln und Wörter ansehen</summary><p class="small">Startsymbol: ${esc(e.grammar.start)} · ${e.grammar.count} Erzeugungen</p><pre>${esc(e.grammar.rules)}</pre><pre>${esc(e.grammar.words)}</pre></details><div class="actions"><button class="primary" data-collection="${e.index}">In der Schreibwerkstatt öffnen</button></div></article>`).join(''):'<section class="panel"><h2>Hier ist Platz für deine ersten Versuche.</h2><p>Bearbeite oder speichere eine Grammatik in der Schreibwerkstatt. Sie erscheint anschliessend hier.</p><a class="button" href="#schreiben/clara?editor=regeln">Mit einer Grammatik anfangen</a></section>';document.querySelectorAll('[data-collection]').forEach(button=>button.onclick=()=>{pending={type:'lyrik:grammar',grammar:namedGrammar(collection[Number(button.dataset.collection)].grammar)};location.hash='#schreiben/'+$('#collection-target').value+'?editor=regeln';});}
function toolbar(route){const writing=route.hash.startsWith('#werkstatt'),name=route.unit==='clara'?'Clara Lösel':'Bodo Wartke';return `<section class="unit-toolbar ${writing?'is-writing':'unit-overview'}"><p>${writing?'Deine Schreibwerkstatt':name+' · Originale und eigene Versuche'}</p><nav class="unit-tabs" aria-label="${writing?'Schreibweise':'Weitere Zugänge'}">${writing?`<a href="#schreiben/clara" ${route.unit==='clara'?'aria-current="page"':''}>Bilder & Stimme</a><a href="#schreiben/wartke" ${route.unit==='wartke'?'aria-current="page"':''}>Form & Lernverse</a><a href="#sammlung">Meine Sammlung</a>`:`<a href="#${route.unit}/${route.unit==='clara'?'inspiration':'hoeren'}">Originale hören</a><a href="#schreiben/${route.unit}">Selbst schreiben</a><a href="#vergleich">Beide verbinden</a>`}</nav></section>`;}
function unitPage(route){currentUnit=route.unit;lastWriter=route.unit;const name=route.unit==='clara'?'Clara Lösel':'Bodo Wartke';return toolbar(route)+`<iframe id="unit-frame" class="unit-frame" title="${esc(name)} in der gemeinsamen Lyrikwerkstatt" src="${route.unit==='clara'?'clara.html':'bodo/'}?integriert=1${esc(route.hash)}" scrolling="no"></iframe>`;}
function render(){requestedScroll=null;loadingFrame=false;lastRoute=location.hash;const route=studioRoute(location.hash);currentUnit=null;$('#main').innerHTML=route.page==='start'?home():route.page==='sammlung'?collectionPage():route.page==='vergleich'?comparison():unitPage(route);paintNav();document.querySelectorAll('[data-studio-note]').forEach(input=>input.oninput=()=>{notes[input.dataset.studioNote]=input.value;save();});if(route.page==='start')bindHome();if(route.page==='vergleich'){$('#compare-write-clara').onclick=()=>startWriting('clara',$('#studio-vergleich-eigen').value);$('#compare-write-wartke').onclick=()=>startWriting('wartke',$('#studio-vergleich-eigen').value);}if(route.page==='sammlung'){$('#collection-search').oninput=event=>{filter=event.target.value;drawCollection();};$('#collection-refresh').onclick=readCollection;readCollection();}if(route.page==='unit'){loadingFrame=true;$('#unit-frame').addEventListener('load',()=>{loadingFrame=false;$('#unit-frame').dataset.fullyLoaded='yes';sendPending();if(requestedScroll===null)window.scrollTo(0,0);else scrollToChild(requestedScroll);});}}
function paintNav(){const route=studioRoute(location.hash);document.querySelectorAll('.studio-nav a').forEach(a=>{const href=a.getAttribute('href');if(href.startsWith('#schreiben/'))a.href='#schreiben/'+lastWriter;const key=a.getAttribute('href').slice(1),writing=route.page==='unit'&&route.hash.startsWith('#werkstatt'),active=route.page===key||(route.page==='unit'&&(key.startsWith('schreiben/')?writing:key.startsWith(route.unit+'/')&&!writing));if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});}
function headerHeight(){return getComputedStyle($('.studio-header')).position==='sticky'?$('.studio-header').getBoundingClientRect().height:0;}
function scrollToChild(top){const frame=$('#unit-frame');if(frame)window.scrollTo({top:Math.max(0,frame.getBoundingClientRect().top+scrollY+top-headerHeight()-16),behavior:'instant'});}
function postViewport(){const frame=$('#unit-frame');if(frame)frame.contentWindow.postMessage({type:'lyrik:viewport',top:Math.max(0,scrollY+headerHeight()-(frame.getBoundingClientRect().top+scrollY)),height:innerHeight-headerHeight()},location.origin);}
window.addEventListener('scroll',postViewport,{passive:true});window.addEventListener('resize',postViewport);
function sendPending(){postViewport();const frame=$('#unit-frame');if(frame&&pending){frame.contentWindow.postMessage(pending,location.origin);pending=null;}}
window.addEventListener('message',event=>{const frame=$('#unit-frame'),data=event.data;if(!frame||event.origin!==location.origin||event.source!==frame.contentWindow||!data||data.unit!==currentUnit&&data.type!=='lyrik:grammar-opened'&&data.type!=='lyrik:error')return;
 if(data.type==='lyrik:height'&&Number.isFinite(data.height)){frame.style.height=Math.max(500,Math.min(60000,data.height))+'px';postViewport();if(loadingFrame&&requestedScroll!==null)scrollToChild(requestedScroll);}
 if(data.type==='lyrik:route'&&typeof data.hash==='string'){history.replaceState(null,'',unitRoute(currentUnit,data.hash));lastRoute=location.hash;lastWriter=currentUnit;paintNav();$('.unit-toolbar').outerHTML=toolbar(studioRoute(location.hash));postViewport();}
 if(data.type==='lyrik:open'&&['clara','wartke'].includes(data.target))location.hash=unitRoute(data.target,data.hash);
 if(data.type==='lyrik:scroll'&&Number.isFinite(data.top)){requestedScroll=data.top;scrollToChild(data.top);}
 if(data.type==='lyrik:grammar-opened')toast('Die Kopie ist in der Schreibwerkstatt geöffnet. Dein vorheriger Regelstand lässt sich dort zurückholen.');
 if(data.type==='lyrik:error')toast(String(data.message||'Die Übernahme ist nicht möglich.').slice(0,500));
});
function download(name,text){const url=URL.createObjectURL(new Blob([text],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('#studio-backup').onclick=()=>{try{download('gemeinsames-lyrikjournal.json',JSON.stringify({format:'lyrik-gemeinsam',version:1,notes,clara:localStorage.getItem('zwischen-zeilen-v1'),wartke:localStorage.getItem('wartke-form-gedaechtnis-v1')},null,2));}catch(error){toast(error.message);}};
$('#studio-import').onchange=async event=>{try{const file=event.target.files[0];if(!file)return;if(file.size>20000000)throw Error('Die Sicherung darf höchstens 20 MB gross sein.');const backup=decodeStudioBackup(await file.text());modal('<h2>Gemeinsames Journal laden?</h2><p>Die Notizen, Texte und Grammatiken beider Zugänge in diesem Browser werden durch die Sicherung ersetzt. Sichere deinen aktuellen Stand vorher, wenn du ihn behalten möchtest.</p><div class="actions"><button id="backup-before-restore">Aktuellen Stand sichern</button><button id="cancel-restore">Abbrechen</button><button class="primary" id="confirm-restore">Sicherung übernehmen</button></div>');$('#backup-before-restore').onclick=$('#studio-backup').onclick;$('#cancel-restore').onclick=()=>$('#studio-dialog').close();$('#confirm-restore').onclick=()=>{const changes={'zwischen-zeilen-v1':backup.clara,'wartke-form-gedaechtnis-v1':backup.wartke,[STUDIO_KEY]:JSON.stringify(backup.notes)},before={};try{for(const key of Object.keys(changes))before[key]=localStorage.getItem(key);$('#unit-frame')?.remove();for(const [key,value] of Object.entries(changes))if(value===null)localStorage.removeItem(key);else localStorage.setItem(key,value);notes=backup.notes;$('#studio-dialog').close();location.hash='#start';render();toast('Das gemeinsame Journal ist geladen.');}catch(error){for(const [key,value] of Object.entries(before)){try{if(value===null)localStorage.removeItem(key);else localStorage.setItem(key,value);}catch{}}toast('Die Sicherung konnte nicht geladen werden: '+error.message);}};}catch(error){toast(error.message);}finally{event.target.value='';}};
$('#studio-info').onclick=()=>modal('<p class="eyebrow">Eine gemeinsame Einheit</p><h2>Originale untersuchen. Eine eigene Stimme entwickeln.</h2><p>Alle bisherigen Inhalte zu Clara Lösel und Bodo Wartke sind in einer gemeinsamen Navigation erreichbar. Die Sammlung führt eigene Editorentwürfe und gespeicherte Grammatiken zusammen. Beim Öffnen in einem anderen Zugang entsteht eine eigene Kopie; frühere Texte bleiben erhalten.</p><p>Vorschlag für zwei Lektionen: ein Original von jeder Person hören, eine Formbeobachtung vergleichen, zwei eigene Vierzeiler entwickeln und die Wirkung oder den fachlichen Kern prüfen. Die ausführlichen Fachplanungen stehen bei den jeweiligen Originalen.</p><p>Die bewegten Übungszeilen auf dem Einstieg sind eigens geschrieben. Originaltexte, Aufnahmen und Quellen bleiben in ihren bisherigen Bereichen gekennzeichnet. Externe Player behalten ihre Ladehinweise und werden nicht automatisch abgespielt.</p><div class="actions"><a class="button" href="#clara/inspiration" id="info-clara">Lösels Originale und Quellen</a><a class="button" href="#wartke/quellen" id="info-wartke">Wartkes Quellen und Unterricht</a></div>');
$('#studio-dialog').addEventListener('click',event=>{if(event.target.closest('a[href^="#"]'))$('#studio-dialog').close();});
window.addEventListener('hashchange',()=>{if(lastRoute!==location.hash){render();$('#main').focus({preventScroll:true});window.scrollTo(0,0);}});
render();
